mapper.select:
select SEQNO,busiDate,startTime,endTime,status,detailAction,taskCname,lastTime,orderno from ( SELECT LOG.SEQNO,DATE_FORMAT(LOG.BUSI_DATE,'%Y%m%d') busiDate,LOG.START_TIME startTime,LOG.END_TIME endTime ,CASE LOG.STATUS WHEN '02' THEN CASE IFNULL(logDetail.ERROR,0) WHEN 0 THEN '02' ELSE '09' END ELSE LOG.STATUS END status ,CASE LOG.STATUS WHEN '02' THEN CASE IFNULL( logDetail.ERROR, 0 ) WHEN 0 THEN concat_ws('', '执行成功', IFNULL( logDetail.success, 0 ), '条' ) ELSE concat_ws('', '执行成功', IFNULL( logDetail.success, 0 ), '条,失败', IFNULL( logDetail.ERROR, 0 ), '条' ) END ELSE LOG.DETAIL_ACTION END detailAction ,GR.TASK_GRP_NAME taskCname,ROUND(LOG.LAST_TIME/1000,2) lastTime,GR.orderno FROM VAL_INTERF_ACTIONLOG LOG left join ( SELECT TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO orderno FROM bok_BATCH_TASK_GRP GROUP BY TASK_GRP_ID, TASK_GRP_NAME,ORDER_NO ) GR on GR.TASK_GRP_ID = CAST(LOG.ORDERNO AS CHAR) LEFT JOIN( SELECT a.parent_seqno,sum(a.success) success,sum(a.ERROR) ERROR FROM ( SELECT parent_seqno parent_seqno, CASE VAL.IS_CHECK WHEN 'Y' THEN LENGHT END success, CASE VAL.IS_CHECK WHEN 'N' THEN LENGHT END ERROR from ( SELECT parent_seqno,IS_CHECK,COUNT(1) LENGHT FROM VAL_INTERFLOG WHERE 1=1 group by parent_seqno,IS_CHECK) val) a group by parent_seqno
) logDetail ON LOG.Seqno=logDetail.parent_seqno WHERE 1=1 AND LOG.EXECTASK_SEQNO = #{execTaskId} ) logdetail WHERE 1=1
AND logdetail.status = #{status}
ORDER BY busiDate,logdetail.orderno
